// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // Owner of a freshly deployed C is address(0); the zero address is the
        // only account satisfying onlyOwner at deployment, so it performs the transfer.
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        // General rule: after transferOwnership(x) succeeds, owner == x, for ALL x.
        assertTrue(c.owner() == newOwner);
    }
}
